/**
 * An animation ticker driving an adapter which sets a particular
 * property in function of the tick.
 *
 * @type {*}
 */
declare class Ticker {
    adapters: any[];
    target: number;
    tick: number;
    interval: number;
    duration: number;
    lastTime: any;
    handlers: any[];
    timerDelegate: () => void;
    intervalId: any;
    caller: any;
    constructor();
    addAdapter(a: any): void;
    onComplete(handler: any): void;
    removeHandler(handler: any): void;
    trigger(): void;
    onStep(): void;
    seekTo(to: any): void;
    seekFromTo(from: any, to: any): void;
    stop(): void;
    play(origin?: any): void;
    reverse(): void;
    initState(): void;
    propagate(): void;
    onTimerEvent(): void;
}
export { Ticker };
